/**
 * MdExplorer - AI Selection
 * =========================
 * When the user selects text inside the rendered document, a floating
 * "✨ Usa AI" button appears near the selection. Clicking it posts the
 * selection to the Angular parent, which opens the AI dialog.
 *
 * The markdown source range comes from the data-mde-line-start/end
 * attributes emitted server-side by MarkdownSourceMapService: they hold
 * 1-based line numbers of the ORIGINAL .md file on disk. Content whose
 * blocks are generated by the pre-conversion transforms (plantuml svg,
 * TOC, toolbars) has no attributes: the button simply does not appear
 * there — a wrong source range is never sent.
 *
 * DOM dependencies:
 * - [data-mde-line-start] / [data-mde-line-end] on rendered blocks
 * - .mdeItemMainPageCenter: main content container (excludes TOC/toolbars)
 * - body[DocumentPath] / body[ConnectionId]
 */

(function () {
    'use strict';

    var BUTTON_ID = 'mdeAiSelectionButton';
    var hideTimer = null;

    function getButton() {
        var btn = document.getElementById(BUTTON_ID);
        if (!btn) {
            btn = document.createElement('button');
            btn.id = BUTTON_ID;
            btn.type = 'button';
            btn.innerHTML = '✨ Usa AI';
            btn.addEventListener('mousedown', function (e) {
                // Before click: keep the selection alive (mousedown would collapse it)
                e.preventDefault();
                e.stopPropagation();
            });
            btn.addEventListener('click', onButtonClick);
            document.body.appendChild(btn);
        }
        return btn;
    }

    function hideButton() {
        var btn = document.getElementById(BUTTON_ID);
        if (btn) {
            btn.style.display = 'none';
            btn.removeAttribute('data-start-line');
            btn.removeAttribute('data-end-line');
        }
    }

    /**
     * Resolves the selection to a 1-based line range of the source .md file.
     * Returns null when the selection cannot be mapped exactly.
     */
    function resolveSelectionRange(selection) {
        if (!selection || selection.isCollapsed || selection.rangeCount === 0) {
            return null;
        }
        var text = selection.toString();
        if (!text || !text.trim()) {
            return null;
        }
        var range = selection.getRangeAt(0);
        var content = document.querySelector('.mdeItemMainPageCenter');
        if (!content || !content.contains(range.commonAncestorContainer)) {
            return null;
        }

        var startBlock = closestMapped(range.startContainer);
        var endBlock = closestMapped(range.endContainer);

        if (startBlock && !endBlock && startBlock.contains(range.commonAncestorContainer)) {
            endBlock = startBlock; // selection fully inside one mapped block
        }
        if (endBlock && !startBlock && endBlock.contains(range.commonAncestorContainer)) {
            startBlock = endBlock;
        }
        if (!startBlock || !endBlock) {
            return null; // unmapped content involved: never guess
        }

        var startLine = Math.min(
            parseInt(startBlock.getAttribute('data-mde-line-start'), 10),
            parseInt(endBlock.getAttribute('data-mde-line-start'), 10));
        var endLine = Math.max(
            parseInt(startBlock.getAttribute('data-mde-line-end'), 10),
            parseInt(endBlock.getAttribute('data-mde-line-end'), 10));
        if (isNaN(startLine) || isNaN(endLine) || endLine < startLine) {
            return null;
        }
        return { startLine: startLine, endLine: endLine, selectedText: text, range: range };
    }

    function closestMapped(node) {
        var el = node.nodeType === Node.ELEMENT_NODE ? node : node.parentElement;
        return el ? el.closest('[data-mde-line-start]') : null;
    }

    function updateButton() {
        var resolved = resolveSelectionRange(window.getSelection());
        if (!resolved) {
            hideButton();
            return;
        }
        var rect = resolved.range.getBoundingClientRect();
        if (!rect || (rect.width === 0 && rect.height === 0)) {
            hideButton();
            return;
        }
        var btn = getButton();
        btn.setAttribute('data-start-line', resolved.startLine);
        btn.setAttribute('data-end-line', resolved.endLine);
        btn.style.display = 'block';
        // Measure after display to clamp inside the viewport
        var btnRect = btn.getBoundingClientRect();
        var left = Math.min(rect.right + 8, window.innerWidth - btnRect.width - 8);
        var top = Math.min(rect.bottom + 8, window.innerHeight - btnRect.height - 8);
        btn.style.left = Math.max(8, left) + 'px';
        btn.style.top = Math.max(8, top) + 'px';
    }

    function onButtonClick() {
        var selection = window.getSelection();
        var resolved = resolveSelectionRange(selection);
        if (!resolved) {
            hideButton();
            return;
        }
        window.parent.postMessage({
            type: 'mde-ai-selection',
            startLine: resolved.startLine,
            endLine: resolved.endLine,
            selectedText: resolved.selectedText,
            documentPath: document.body.getAttribute('DocumentPath') || '',
            connectionId: document.body.getAttribute('ConnectionId') || ''
        }, '*');
        hideButton();
        if (selection) {
            selection.removeAllRanges();
        }
    }

    function scheduleUpdate() {
        if (hideTimer) {
            clearTimeout(hideTimer);
        }
        hideTimer = setTimeout(updateButton, 150);
    }

    document.addEventListener('selectionchange', scheduleUpdate);
    document.addEventListener('mouseup', scheduleUpdate);
    window.addEventListener('scroll', hideButton, true);
    window.addEventListener('resize', hideButton);

    console.log('✅ [AI-SELECTION] ai-selection.js loaded');
})();
